 s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);s.settimeout(1);s.sendto(msg,('127.0.0.11',53))
 try:
  d=s.recv(4096); print(name,typ,d.hex())
 except Exception as e: print(name,e)
